331	    /**
332	     * Emits the audit trail for a freshly created owner: the human-readable {@code AUDIT} line and the
333	     * structured {@link OwnerCreatedEvent}, in that order. Both carry the owner's primary identifier,
334	     * the unified {@code memberId} returned by {@link #primaryIdentifier}, so keeping the two emissions
335	     * together in one place lets the audit trail's view of the owner's identity change in a single spot.
336	     * The event's {@code seq} is bumped exactly once here, so every emitted event carries a strictly
337	     * larger sequence number than the create before it.
338	     *
339	     * @param owner    the freshly created and persisted owner, already stamped with its identity
340	     * @param ownerDto the owner's mapped DTO, the source of the derived {@code membershipLevel} carried
341	     *                 on the audit trail
342	     */
343	    private void emitOwnerCreatedAudit(Owner owner, OwnerDto ownerDto) {
344	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
345	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
346	            ownerDto.getMembershipLevel());
347	        OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
348	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
349	        AUDIT.info(event.toJson());
350	    }
351	
352	    /**
353	     * Enqueues the freshly created owner's welcome notification by emitting a single line to the
354	     * dedicated {@code NOTIFY} logger. The line carries the owner's id and its unified
355	     * {@code memberId} (routed through {@link #primaryIdentifier}), the two values a downstream
356	     * consumer needs to address the welcome to the new member.
357	     *
358	     * @param owner the freshly created and persisted owner, already stamped with its {@code memberId}
359	     */
360	    private void enqueueWelcomeNotification(Owner owner) {
361	        NOTIFY.info("welcome notification queued ownerId={} memberId={}",
362	            owner.getId(), primaryIdentifier(owner));
363	    }
364	
365	    /**
366	     * The owner's primary identifier, as carried on the {@link OwnerCreatedEvent} audit event: the
367	     * unified {@code memberId}. Routing the audit event through this single accessor keeps the audit
368	     * trail's notion of the owner's identity in one place.
369	     *
370	     * @param owner the freshly created owner, already stamped with its {@code memberId}
371	     * @return the owner's primary identifier
372	     */
373	    private String primaryIdentifier(Owner owner) {
374	        return owner.getMemberId();
375	    }
376	
377	    /**
378	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
379	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
380	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
381	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
382	     *
383	     * @return the non-blank idempotency key, or {@code null} when none was supplied
384	     */
385	    private String idempotencyKey() {
386	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
387	            return null;
388	        }
389	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
390	        return isBlank(key) ? null : key.trim();
391	    }
392	
393	    /**
394	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
395	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
396	     * the request body already rejects null and empty values, but permits whitespace-only strings
397	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
398	     * that gap so every required field must carry a non-blank value.
399	     *
400	     * @param ownerFieldsDto the submitted owner fields
401	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
402	     */
403	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
404	        List<String> missing = new ArrayList<>();
405	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
406	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
407	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
408	            missing.add("address");
409	        }
410	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
411	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
412	        if (!missing.isEmpty()) {
413	            throw new InvalidOwnerFieldsException(missing);
414	        }
415	    }
416	
417	    /**
418	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
419	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
420	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
421	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
422	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
423	     * {@link PostcodeValidator}.
424	     *
425	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
426	     *                       {@link #rejectBlankOwnerFields} having already run)
427	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
428	     */
429	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
430	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
431	            throw new InvalidOwnerFieldsException(List.of("postcode"));
432	        }
433	    }
434	
435	    private void addIfBlank(List<String> missing, String fieldName, String value) {
436	        if (isBlank(value)) {
437	            missing.add(fieldName);
438	        }
439	    }
440	
441	    private boolean isBlank(String value) {
442	        return value == null || value.isBlank();
443	    }
444	
445	    /**
446	     * Normalizes the submitted address on create to its canonical form (see
447	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
448	     * stored and returned, and the form every later address comparison (the required-field check,
449	     * household duplicate detection and the shared household id) is judged on. The structured fields
450	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
451	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
452	     * derived from them when a structured {@code addressLine1} is present, falling back to the
453	     * normalized flat {@code address} otherwise. Any absent field is left absent so
454	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
455	     * after normalization likewise reduces to the empty string and is rejected there.
456	     *
457	     * @param ownerFieldsDto the submitted owner fields
458	     */
459	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
460	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
461	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
462	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
463	        ownerFieldsDto.setAddressLine1(addressLine1);
464	        ownerFieldsDto.setAddressLine2(addressLine2);
465	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
466	    }
467	
468	    /**
469	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
470	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
471	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
472	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
473	     * is the single value every later reader of the address (the required-field check, household
474	     * duplicate detection and the shared household id) is judged on.
475	     *
476	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
477	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
478	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
479	     * @return the composed flat address, or {@code null} when no address form was supplied
480	     */
481	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
482	        if (isBlank(addressLine1)) {
483	            return flatAddress;
484	        }
485	        if (isBlank(addressLine2)) {
486	            return addressLine1;
487	        }
488	        return addressLine1 + " " + addressLine2;
489	    }
490	
491	    /**
492	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
493	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
494	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
495	     * {@code 400 Bad Request}.
496	     *
497	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
498	     *                       {@link #rejectBlankOwnerFields} having already run)
499	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
500	     */
501	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
502	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
503	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
504	        ownerFieldsDto.setTelephone(normalized);
505	    }
506	
507	    /**
508	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
509	     * untouched (email is optional). When present it is reduced to its canonical form (see
510	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
511	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
512	     *
513	     * @param ownerFieldsDto the submitted owner fields
514	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
515	     *                                     or its domain is on the disposable-domain blocklist
516	     */
517	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
518	        String email = ownerFieldsDto.getEmail();
519	        if (email == null || email.isBlank()) {
520	            return;
521	        }
522	        String normalized = EmailNormalizer.normalize(email)
523	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
524	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
525	            throw new InvalidOwnerFieldsException(List.of("email"));
526	        }
527	        ownerFieldsDto.setEmail(normalized);
528	    }
529	
530	    /**
531	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
532	     * duplicate detection is now expressed through the single derived {@code identityKey}
533	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
534	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
535	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
536	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
537	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
538	     * carry different telephones have different keys and are both allowed (they are instead recorded as
539	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
540	     * longer makes a duplicate.
541	     *
542	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
543	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
544	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
545	     */
546	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
547	        String identityKey = OwnerIdentity.identityKey(
548	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
549	        boolean inUse = activeOwners().stream()
550	            .map(OwnerIdentity::identityKey)
551	            .anyMatch(identityKey::equals);
552	        if (inUse) {
553	            throw new DuplicateOwnerIdentityException(identityKey);
554	        }
555	    }
556	
557	    /**
558	     * The owners considered by duplicate detection: every persisted owner except those flagged
559	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
560	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
561	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
562	     * alone. Only owners already persisted (before this create) are included.
563	     *
564	     * @return the non-deleted owners currently persisted
565	     */
566	    private List<Owner> activeOwners() {
567	        return this.clinicService.findAllOwners().stream()
568	            .filter(owner -> !owner.isDeleted())
569	            .toList();
570	    }
571	
572	    /**
573	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
574	     * both match the submitted values, compared case-insensitively. The count reflects only owners
575	     * already persisted at the time of the create, so the owner being created is never included.
576	     *
577	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
578	     *                  having already run)
579	     * @param lastName  the submitted last name (non-blank here)
580	     * @return the number of existing owners sharing the same first and last name
581	     */
582	    private int countNamesakes(String firstName, String lastName) {
583	        return (int) this.clinicService.findAllOwners().stream()
584	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
585	                && lastName.equalsIgnoreCase(owner.getLastName()))
586	            .count();
587	    }
588	
589	    /**
590	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
591	     * whose stored {@code householdId} equals the value derived for the owner being created. The
592	     * count reflects only owners already persisted at the time of the create, so the owner being
593	     * created is never included; callers add one to obtain the household size after this create.
594	     *
595	     * @param householdId the household identifier derived for the owner being created (see
596	     *                    {@link HouseholdNormalizer#toHouseholdId})
597	     * @return the number of existing owners already sharing that household
598	     */
599	    private int countHouseholdMembers(String householdId) {
600	        return householdMembers(householdId).size();
601	    }
602	
603	    /**
604	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
605	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
606	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
607	     * created is never among them.
608	     *
609	     * @param householdId the household identifier derived for the owner being created (see
610	     *                    {@link HouseholdNormalizer#toHouseholdId})
611	     * @return the existing owners already sharing that household (empty when {@code householdId} is
612	     *         {@code null})
613	     */
614	    private List<Owner> householdMembers(String householdId) {
615	        if (householdId == null) {
616	            return List.of();
617	        }
618	        return this.clinicService.findAllOwners().stream()
619	            .filter(member -> householdId.equals(member.getHouseholdId()))
620	            .toList();
621	    }
622	
623	    /**
624	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
625	     * {@code membershipLevel} among their existing household members. The owner's own level is the
626	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
627	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
628	     * owner's own level is returned unchanged.
629	     *
630	     * @param owner the owner being created, already stamped with its household id and size
631	     * @return the (possibly capped) membership level to stamp on the owner
632	     */
633	    private int cappedMembershipLevel(Owner owner) {
634	        int ownLevel = this.ownerMapper.membershipLevel(owner);
635	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
636	            .mapToInt(this.ownerMapper::membershipLevel)
637	            .max();
638	        return maxHouseholdLevel.isPresent()
639	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
640	            : ownLevel;
641	    }
642	
643	    /**
644	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
645	     * owner with an address taken from the request, so routing that through this single method keeps the
646	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
647	     * household id.
648	     *
649	     * @param ownerFieldsDto the submitted owner fields
650	     * @return the address to store on the owner
651	     */
652	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
653	        return ownerFieldsDto.getAddress();
654	    }
655	
656	    /**
657	     * Derives the household id an owner should carry from its submitted fields (see
658	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
659	     * household id, so routing them through this single method keeps them agreed on which of the
660	     * owner's fields key the household.
661	     *
662	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
663	     *                       {@link #rejectBlankOwnerFields} having already run on create)
664	     * @return the owner's household id
665	     */
666	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
667	        return HouseholdNormalizer.toHouseholdId(
668	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
669	    }
670	
671	    /**
672	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
673	     * is none. The create has already cleared the hard-duplicate identity check
674	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
675	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
676	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
677	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
678	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
679	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
680	     * at the original record; owners with no postcode never match, since a shared postcode is required.
681	     *
682	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
683	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
684	     *         duplicate
685	     */
686	    private Integer findPossibleDuplicate(Owner owner) {
687	        String postcode = owner.getPostcode();
688	        if (postcode == null) {
689	            return null;
690	        }
691	        String identityKey = OwnerIdentity.identityKey(owner);
692	        String lastNameCode = Soundex.soundex(owner.getLastName());
693	        return activeOwners().stream()
694	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
695	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
696	            .filter(existing -> postcode.equals(existing.getPostcode()))
697	            .map(Owner::getId)
698	            .filter(Objects::nonNull)
699	            .min(Integer::compareTo)
700	            .orElse(null);
701	    }
702	
703	    /**
704	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
705	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
706	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
707	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
708	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
709	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
710	     * duplicate, so it is never flagged.
711	     *
712	     * @param owner           the owner being created, with telephone already normalized and
713	     *                        lastName/postcode set
714	     * @param sharesHousehold whether the request opted in to sharing a household
715	     */
716	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
717	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
718	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
719	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
720	    }
721	
722	    /**
723	     * Counts how many existing owners already live in the given city. The submitted city is compared
724	     * case-insensitively against every existing owner's stored city. The result drives both the hard
725	     * capacity rejection (see {@link #rejectCityAtCapacity}) and the {@code capacityWarning} flag.
726	     *
727	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
728	     *             run)
729	     * @return the number of existing owners whose city matches the submitted city
730	     */
731	    private long countOwnersInCity(String city) {
732	        return this.clinicService.findAllOwners().stream()
733	            .map(Owner::getCity)
734	            .filter(Objects::nonNull)
735	            .filter(city::equalsIgnoreCase)
736	            .count();
737	    }
738	
739	    /**
740	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
741	     * A city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
742	     *
743	     * @param city         the submitted city (used only to report the conflict)
744	     * @param ownersInCity the number of owners the city already holds (see {@link #countOwnersInCity})
745	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
746	     */
747	    private void rejectCityAtCapacity(String city, long ownersInCity) {
748	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
749	            throw new OwnerCityAtCapacityException(city);
750	        }
751	    }
752	
753	    /**
754	     * Resolves the effective registration date for a create, rolled onto a business day. The
755	     * supplied date is used when present, otherwise the server's current date; either way the result
756	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
757	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
758	     * stored {@code registrationDate}, the membership number's year segment and the daily
759	     * create-limit's per-day count - is judged on this adjusted date.
760	     *
761	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
762	     *                                 default to the server's current date
763	     * @return the effective registration date, guaranteed to fall on a business day
764	     */
765	    /**
766	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
767	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
768	     * adjustment; a future date cannot describe a registration that has already happened, so it is
769	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
770	     * server's current date) and any date on or before today are accepted.
771	     *
772	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
773	     *                                 omitted
774	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
775	     */
776	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
777	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
778	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
779	        }
780	    }
781	
782	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
783	        LocalDate registrationDate =
784	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
785	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
786	    }
787	
788	    /**
789	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
790	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
791	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
792	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
793	     * Too Many Requests}.
794	     *
795	     * @param registrationDate   the create's effective registration date, already rolled onto a
796	     *                           business day by {@link #effectiveRegistrationDate}
797	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
798	     *                           {@code registrationDate} equals {@code registrationDate}
799	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
800	     *                                              owner registrations
801	     */
802	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
803	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
804	            throw new OwnerDailyRegistrationLimitException(registrationDate);
805	        }
806	    }
807	
808	    /**
809	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
810	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
811	     * bulk-signup warning are judged on.
812	     *
813	     * @param registrationDate the create's effective registration date, already rolled onto a business
814	     *                         day by {@link #effectiveRegistrationDate}
815	     * @return the number of existing owners registered on that day
816	     */
817	    private long countRegisteredOn(LocalDate registrationDate) {
818	        return this.clinicService.findAllOwners().stream()
819	            .map(Owner::getRegistrationDate)
820	            .filter(registrationDate::equals)
821	            .count();
822	    }
823	}
